const rivalExists = `-- name: RivalExists :one
SELECT EXISTS(SELECT 1 FROM rival_channels WHERE id = $1)::bool AS exists
`

func (q *Queries) RivalExists(ctx context.Context, id string) (bool, error) {
	row := q.db.QueryRow(ctx, rivalExists, id)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

